from pathlib import Path
p=Path('src/http_control/windows.rs');s=p.read_text(encoding='utf-8-sig');s=s.replace('#[cfg(test)]std::thread_local!{static OBSERVED:', '#[cfg(test)]std::thread_local!{static CLOSE_FAULT:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};static OBSERVED:')
s=s.replace('if WinHttpCloseHandle(h)==0{diag.push(format!("关闭HTTP请求失败：{}",std::io::Error::last_os_error()));}', 'if WinHttpCloseHandle(h)==0{diag.push(format!("关闭HTTP请求失败：{}",std::io::Error::last_os_error()));}#[cfg(test)]if CLOSE_FAULT.with(|f|f.get()){diag.push("关闭HTTP请求失败：故障注入，实际关闭仍执行".into());}')
s=s.replace('let mut result=unsafe{execute(&r,&c,local,&ctx,&mut handles,&mut scratch)};', 'let execution=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||unsafe{execute(&r,&c,local,&ctx,&mut handles,&mut scratch)}));')
s=s.replace('handles.close(&ctx,&mut diagnostics);\n if result.is_ok()', 'handles.close(&ctx,&mut diagnostics);\n let mut result=match execution{Ok(result)=>result,Err(panic)=>std::panic::resume_unwind(panic)};\n if result.is_ok()')
s=s.replace(' #[test]fn cancellation_completion_races_repeat_without_callbacks_left()', ''' #[test]fn close_diagnostics_never_hide_success_or_global_reason(){let server=Server::new("normal");CLOSE_FAULT.with(|f|f.set(true));let report=run(server.request(5000,4096),control());CLOSE_FAULT.with(|f|f.set(false));assert!(matches!(report.result,Err(HttpFailure::Io{..})));assert_eq!(report.diagnostics.len(),1);drop(server);let server=Server::new("slowbody");CLOSE_FAULT.with(|f|f.set(true));let report=run(server.request(5000,4096),HttpControl{deadline:Some(Instant::now()+Duration::from_millis(80)),cancel:None});CLOSE_FAULT.with(|f|f.set(false));assert!(matches!(report.result,Err(HttpFailure::Deadline)));assert_eq!(report.diagnostics.len(),1);}
 #[test]fn cancellation_completion_races_repeat_without_callbacks_left()''')
p.write_text(s,encoding='utf-8')
